// Apply this after project evaluation too, so plugin build.gradle values do
// not override the compatibility floor required by current AndroidX artifacts.
subprojects {
    pluginManager.withPlugin("com.android.library") {
        extensions.findByType<com.android.build.api.dsl.LibraryExtension>()?.compileSdk = 36
    }
    afterEvaluate {
        pluginManager.withPlugin("com.android.library") {
            extensions.findByType<com.android.build.api.dsl.LibraryExtension>()?.compileSdk = 36
        }
    }
